import{c as n,Q as i,j as t,m as e}from"./chunks/framework.BPKcPtvA.js";const u=JSON.parse('{"title":"Tagihan & Pembayaran PPPoE","description":"","frontmatter":{},"headers":[],"relativePath":"panduan/pppoe/tagihan.md","filePath":"panduan/pppoe/tagihan.md"}'),s={name:"panduan/pppoe/tagihan.md"};function r(l,a,h,o,p,g){return i(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="tagihan-pembayaran-pppoe" tabindex="-1">Tagihan &amp; Pembayaran PPPoE <a class="header-anchor" href="#tagihan-pembayaran-pppoe" aria-label="Permalink to &quot;Tagihan &amp; Pembayaran PPPoE&quot;">​</a></h1><hr><h2 id="generate-tagihan-bulanan" tabindex="-1">Generate Tagihan Bulanan <a class="header-anchor" href="#generate-tagihan-bulanan" aria-label="Permalink to &quot;Generate Tagihan Bulanan&quot;">​</a></h2><p>Tagihan PPPoE di-generate <strong>otomatis setiap hari pukul 01:00</strong> untuk periode bulan berjalan. Jika ada pelanggan baru yang ditambahkan di tengah bulan, tagihannya akan otomatis muncul keesokan harinya.</p><p>Proses ini bersifat <strong>idempoten</strong> — jika tagihan untuk bulan tersebut sudah ada, tidak akan dibuat duplikat.</p><h3 id="generate-manual" tabindex="-1">Generate Manual <a class="header-anchor" href="#generate-manual" aria-label="Permalink to &quot;Generate Manual&quot;">​</a></h3><p>Untuk men-generate tagihan diluar jadwal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pppoe:generate-monthly-billings</span></span></code></pre></div><p>Opsi tambahan:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Untuk router tertentu</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pppoe:generate-monthly-billings</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --router=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uuid</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Untuk bulan/tahun tertentu</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pppoe:generate-monthly-billings</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --month=6</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --year=2025</span></span></code></pre></div><hr><h2 id="halaman-billing" tabindex="-1">Halaman Billing <a class="header-anchor" href="#halaman-billing" aria-label="Permalink to &quot;Halaman Billing&quot;">​</a></h2><p>Buka router → <strong>PPPoE → Billing</strong> untuk melihat semua tagihan aktif.</p><p>Filter yang tersedia:</p><ul><li><strong>Status</strong> — Semua / Belum Bayar / Lunas / Terlambat</li><li><strong>Pencarian</strong> — Nama atau username pelanggan</li></ul><hr><h2 id="pembayaran-via-midtrans" tabindex="-1">Pembayaran via Midtrans <a class="header-anchor" href="#pembayaran-via-midtrans" aria-label="Permalink to &quot;Pembayaran via Midtrans&quot;">​</a></h2><p>Jika Midtrans dikonfigurasi di pengaturan, tersedia pembayaran online:</p><ol><li>Buka detail tagihan pelanggan</li><li>Klik <strong>Buat Link Bayar</strong> — sistem akan men-generate Snap Token Midtrans</li><li>Klik <strong>Kirim WA</strong> untuk mengirim link pembayaran ke pelanggan via WhatsApp</li><li>Pelanggan klik link → halaman pembayaran Midtrans terbuka → pilih metode bayar</li><li>Setelah pembayaran berhasil, webhook Midtrans otomatis mengkonfirmasi tagihan</li></ol><h3 id="metode-pembayaran-yang-didukung" tabindex="-1">Metode Pembayaran yang Didukung <a class="header-anchor" href="#metode-pembayaran-yang-didukung" aria-label="Permalink to &quot;Metode Pembayaran yang Didukung&quot;">​</a></h3><p>Semua metode yang aktif di akun Midtrans Anda: virtual account bank, QRIS, kartu kredit, dan lainnya.</p><hr><h2 id="konfirmasi-pembayaran-manual" tabindex="-1">Konfirmasi Pembayaran Manual <a class="header-anchor" href="#konfirmasi-pembayaran-manual" aria-label="Permalink to &quot;Konfirmasi Pembayaran Manual&quot;">​</a></h2><p>Untuk pembayaran yang diterima secara langsung (tunai, transfer):</p><ol><li>Buka halaman detail tagihan atau detail pelanggan</li><li>Klik <strong>Catat Pembayaran</strong></li><li>Isi metode pembayaran dan nomor referensi (opsional)</li><li>Klik <strong>Konfirmasi</strong> — tagihan berubah status menjadi <strong>Lunas</strong></li></ol><hr><h2 id="laporan-keuangan" tabindex="-1">Laporan Keuangan <a class="header-anchor" href="#laporan-keuangan" aria-label="Permalink to &quot;Laporan Keuangan&quot;">​</a></h2><p>Buka router → <strong>Keuangan</strong> untuk melihat rekap finansial:</p><ul><li><strong>Total tagihan</strong> bulan ini</li><li><strong>Total pembayaran</strong> yang sudah masuk</li><li><strong>Sisa tunggakan</strong></li><li>Riwayat transaksi dengan filter periode</li></ul><hr><h2 id="status-tagihan" tabindex="-1">Status Tagihan <a class="header-anchor" href="#status-tagihan" aria-label="Permalink to &quot;Status Tagihan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Arti</th></tr></thead><tbody><tr><td><strong>Belum Bayar</strong></td><td>Tagihan aktif, belum melewati jatuh tempo</td></tr><tr><td><strong>Terlambat</strong></td><td>Tagihan belum dibayar, sudah melewati jatuh tempo</td></tr><tr><td><strong>Lunas</strong></td><td>Tagihan sudah dikonfirmasi/dibayar</td></tr></tbody></table>`,32)])])}const k=n(s,[["render",r]]);export{u as __pageData,k as default};
